+function clamp_to_byte {
+  returns Bits<8>
+  arguments Bits<32> value
+  description { Clamp a 32-bit value to [0, 255]. }
+  body {
+    if (value > 255) {
+      return 8'd255;  # early return
+    }
+    return value[7:0];
+  }
